public boolean isInWhitelist(String componentIdentification, String componentVersion) {
    if (StringUtils.isBlank(componentIdentification)) {
        return false;
    }
    String config = whitelistConfig;             // 配置中心注入，@RefreshScope 热刷新
    if (StringUtils.isBlank(config)) {
        return false;
    }
    for (String entry : config.split(",")) {
        String item = entry.trim();
        if (item.isEmpty()) {
            continue;
        }
        if (!item.contains(":")) {
            // 第一代粒度：整个组件命中
            if (item.equals(componentIdentification)) {
                return true;
            }
            continue;
        }
        // 第二代粒度：组件:版本，冒号是粒度开关
        String[] parts = item.split(":", 2);
        if (!parts[0].equals(componentIdentification)) {
            continue;
        }
        if (StringUtils.isBlank(componentVersion)) {
            continue;
        }
        if (parts[1].equals(componentVersion)) {
            return true;
        }
    }
    return false;
}

public boolean isWebH5GroupEnabled(String componentIdentification, String componentVersion) {
    if (!isInWhitelist(componentIdentification, componentVersion)) {
        return false;
    }
    try {
        ComponentVersionInfo info = componentVersionInfoService
                .queryByComponentAndVersion(componentIdentification, componentVersion);
        if (info == null) {
            return false;
        }
        // 只有 web 框架才启用分组菜单，H5 组件本身就是移动端
        return FRAMEWORK_TYPE_WEB.equals(info.getFrameworkType());
    } catch (Exception e) {
        log.warn("query frameworkType failed, treat as disabled. identification: {}, version: {}",
                componentIdentification, componentVersion, e);
        return false;
    }
}

public Long addMenu(ComponentMenuBo menuBo, HttpServletRequest request) {
    ComponentMenu menu = new ComponentMenu();
    BeanUtils.copyProperties(menuBo, menu);
    // 开关只影响「是否写分组列」，不影响菜单本身能不能存
    if (grayService.isWebH5GroupEnabled(menuBo.getComponentIdentification(),
            menuBo.getComponentVersion())) {
        menu.setC_menu_group(normalizeMenuGroup(menuBo.getMenuGroup()));
    } else {
        // 未命中灰度：显式置 null，避免前端偷偷传了值把老组件写成新形态
        menu.setC_menu_group(null);
    }
    menu.setI_sort(queryNextSort(menu.getC_component_id(), menu.getR_component_menu()));
    componentMenuDao.save(menu);
    return menu.getId();
}
